import {
    _decorator,
    Component,
    EventKeyboard,
    Input,
    JsonAsset,
    KeyCode,
    Node,
    input,
} from 'cc';
import { PlayerGridMove } from './GameArea/PlayerGridMove';
import { MapNpcInteract } from './MapNpcInteract';
import { StoryLocalTaskState } from './StoryLocalTaskState';
import { StoryMapModel } from './StoryMapModel';
import type { StoryNpcEvent } from './StoryMapTypes';
import { StoryUIViewController } from './StoryUIViewController';

const { ccclass, property } = _decorator;

/**
 * 大世界剧情交互（客户端 MVP）
 *
 * 自动挂载：GameArea 上的 WorldOnlineSync 会在启动后调用 StoryWorldInteract.ensureOn(gameArea)，
 * 为本节点添加本组件、注入 map Json（取首个 MapNpcInteract）、并在 CanvasRoot(UI) 上确保 StoryUIViewController。
 *
 * 手动绑定（若关闭自动逻辑）：将本组件挂在 GameArea，指定 mapConfig、playerNode、Canvas 上的 StoryUIViewController。
 */
@ccclass('StoryWorldInteract')
export class StoryWorldInteract extends Component {
    @property({ type: JsonAsset, tooltip: '默认可留空，ensureOn 会从子节点 MapNpcInteract 拷贝' })
    mapConfig: JsonAsset | null = null;

    @property({ type: Node, tooltip: '默认可留空，将尝试 WorldOnlineSync.localPlayerMove 或 WorldRoot 下 PlayerGridMove' })
    playerNode: Node | null = null;

    @property({ type: StoryUIViewController, tooltip: '默认可留空，自动使用 CanvasRoot(UI) 上组件' })
    ui: StoryUIViewController | null = null;

    @property({ tooltip: '将任务与已完成事件写入 localStorage（键含 mapCode）' })
    persistProgress = true;

    private _model: StoryMapModel | null = null;
    private _taskState: StoryLocalTaskState | null = null;
    private _nearest: MapNpcInteract | null = null;

    /**
     * 由 WorldOnlineSync 延迟调用：确保 GameArea 上存在剧情交互与 UI 控制器。
     */
    static ensureOn(gameArea: Node): StoryWorldInteract | null {
        if (!gameArea?.isValid) return null;
        let story = gameArea.getComponent(StoryWorldInteract);
        if (!story) story = gameArea.addComponent(StoryWorldInteract);

        const npc = gameArea.getComponentInChildren(MapNpcInteract);
        if (npc?.mapConfig && !story.mapConfig) {
            story.mapConfig = npc.mapConfig;
        }

        const canvasRoot = gameArea.getChildByName('CanvasRoot(UI)');
        if (canvasRoot?.isValid) {
            let ui = canvasRoot.getComponent(StoryUIViewController);
            if (!ui) ui = canvasRoot.addComponent(StoryUIViewController);
            if (!story.ui) story.ui = ui;
        }

        return story;
    }

    onLoad() {
        this._rebuildModel();
    }

    start() {
        if (!this.mapConfig) {
            const npc = this.node.getComponentInChildren(MapNpcInteract);
            if (npc?.mapConfig) this.mapConfig = npc.mapConfig;
        }
        this._rebuildModel();
    }

    onEnable() {
        input.on(Input.EventType.KEY_DOWN, this._onKeyDown, this);
    }

    onDisable() {
        input.off(Input.EventType.KEY_DOWN, this._onKeyDown, this);
    }

    update() {
        if (!this._model || !this._taskState || !this.ui) {
            this._rebuildModel();
        }
        const ui = this.ui;
        if (!ui || !this._model || !this._taskState) return;
        ui.ensureRefs();

        if (ui.isBlockingInput()) {
            ui.showInteractPrompt(false);
            this._nearest = null;
            return;
        }

        const player = this._resolvePlayerNode();
        if (!player?.isValid) {
            ui.showInteractPrompt(false);
            return;
        }

        const npcs = this.node.getComponentsInChildren(MapNpcInteract);
        let best: MapNpcInteract | null = null;
        let bestD = this._model.maxInteractDistance + 1;

        const pw = player.worldPosition;
        for (let i = 0; i < npcs.length; i++) {
            const c = npcs[i];
            if (!c?.npcUid) continue;
            const anchor = c.interactAnchor?.isValid ? c.interactAnchor : c.node;
            const aw = anchor.worldPosition;
            const dx = pw.x - aw.x;
            const dy = pw.y - aw.y;
            const d = Math.sqrt(dx * dx + dy * dy);
            if (d < bestD && d <= this._model.maxInteractDistance) {
                bestD = d;
                best = c;
            }
        }

        this._nearest = best;
        ui.showInteractPrompt(!!best, '按 E 对话');
    }

    private _rebuildModel(): void {
        if (!this.mapConfig?.json) return;
        this._model = new StoryMapModel(this.mapConfig);
        const code = this._model.raw.mapCode ?? `map_${this._model.raw.mapId ?? 0}`;
        this._taskState = new StoryLocalTaskState(code, this.persistProgress);

        if (!this.ui?.isValid) {
            const canvasRoot = this.node.getChildByName('CanvasRoot(UI)');
            this.ui = canvasRoot?.getComponent(StoryUIViewController) ?? null;
        }
    }

    private _resolvePlayerNode(): Node | null {
        if (this.playerNode?.isValid) return this.playerNode;
        const root = this.node.getChildByName('WorldRoot') ?? this.node;
        const pgms = root.getComponentsInChildren(PlayerGridMove);
        for (let i = 0; i < pgms.length; i++) {
            const p = pgms[i];
            if (p?.enabled && p.node?.isValid) {
                this.playerNode = p.node;
                return p.node;
            }
        }
        const fallback = pgms[0]?.node ?? this.node.getComponentInChildren(PlayerGridMove)?.node;
        if (fallback?.isValid) {
            this.playerNode = fallback;
            return fallback;
        }
        return null;
    }

    private _onKeyDown(e: EventKeyboard): void {
        if (e.keyCode !== KeyCode.KEY_E) return;
        if (!this.ui || !this._model || !this._taskState) return;
        this.ui.ensureRefs();
        if (this.ui.isBlockingInput()) return;
        if (!this._nearest?.npcUid) return;

        const ev = this._model.getFirstEligibleEvent(this._nearest.npcUid, this._taskState);
        if (!ev) {
            this.ui.showToast('当前没有可进行的剧情');
            return;
        }
        this._runEvent(ev);
    }

    private _runEvent(ev: StoryNpcEvent): void {
        const ui = this.ui!;
        const state = this._taskState!;
        const model = this._model!;

        const t = ev.eventType;
        if (t === 'dialog') {
            const dlg = model.getDialogue(ev.client.dialogueScriptId);
            if (!dlg) {
                ui.showToast(`缺少对白脚本：${ev.client.dialogueScriptId ?? ''}`);
                return;
            }
            ui.runDialogue(dlg, (cancelled) => {
                if (cancelled) return;
                state.applyServerEffects(ev.server.effects ?? []);
                state.markEventCompleted(ev.eventId);
            });
            return;
        }

        if (t === 'task') {
            const hint = ev.client.taskUiHint ?? '';
            state.applyServerEffects(ev.server.effects ?? []);
            state.markEventCompleted(ev.eventId);
            if (hint.length > 0) ui.showToast(hint, 2.8);
            return;
        }

        if (t === 'battle' || t === 'teleport') {
            const cid = ev.client.choiceScriptId;
            const choice = model.getChoice(cid);
            if (!choice) {
                ui.showToast(`缺少选项脚本：${cid ?? ''}`);
                return;
            }
            ui.runChoice(choice, (opt) => {
                const lines: string[] = [];
                if (opt.systemTip?.trim()) lines.push(opt.systemTip.trim());
                if (opt.forcedResult) lines.push('（剧情分支：后续将对接战斗/强制结果）');
                if (t === 'battle') {
                    lines.push(`战斗入口待对接（${ev.server.battleRef ?? '无 battleRef'}）`);
                    state.applyServerEffects(ev.server.effects ?? []);
                } else {
                    lines.push('传送入口待对接（MVP）');
                }
                if (lines.length > 0) ui.showToast(lines.join('\n'), 3.6);
                state.markEventCompleted(ev.eventId);
            });
            return;
        }

        ui.showToast(`未支持的事件类型：${t}`);
    }
}
